const families = Object.keys(BY_FAMILY);
if (families.length !== 16) throw new Error(`Expected 16 families, got ${families.length}`);

const lines = [];
lines.push(`import type { TrackFamily } from "./track-family";`);
lines.push(``);
lines.push(`export type TrackDef = {`);
lines.push(`  slug: string;`);
lines.push(`  role: string;`);
lines.push(`  setting: string;`);
lines.push(`  blurb: string;`);
lines.push(`  family: TrackFamily;`);
lines.push(`  themes: [string, string, string, string, string];`);
lines.push(`};`);
lines.push(``);
lines.push(`export const TRACK_DEFS: TrackDef[] = [`);

const seen = new Set();
let total = 0;
for (const [family, tracks] of Object.entries(BY_FAMILY)) {
  if (tracks.length !== 20) throw new Error(`${family}: ${tracks.length} tracks`);
  for (const [slug, role, setting, blurb, themes] of tracks) {
    if (seen.has(slug)) throw new Error(`Duplicate slug ${slug}`);
    seen.add(slug);
    total++;
    const t = themes.map((x) => JSON.stringify(x)).join(", ");
    lines.push(`  {`);
    lines.push(`    slug: ${JSON.stringify(slug)},`);
    lines.push(`    role: ${JSON.stringify(role)},`);
    lines.push(`    setting: ${JSON.stringify(setting)},`);
    lines.push(`    blurb: ${JSON.stringify(blurb)},`);
    lines.push(`    family: ${JSON.stringify(family)},`);
    lines.push(`    themes: [${t}],`);
    lines.push(`  },`);
  }
}
lines.push(`];`);
lines.push(``);
lines.push(`if (TRACK_DEFS.length !== 320) {`);
lines.push(`  throw new Error(\`Expected 320 track defs, got \${TRACK_DEFS.length}\`);`);
lines.push(`}`);
lines.push(``);

writeFileSync("src/lib/track-defs.ts", lines.join("\n") + "\n");
console.log("wrote", total, "track defs");
